import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十六卦 明夷 地火明夷 坤上离下","description":"周易 - 第三十六卦 明夷 地火明夷 坤上离下","frontmatter":{"title":"第三十六卦 明夷 地火明夷 坤上离下","description":"周易 - 第三十六卦 明夷 地火明夷 坤上离下"},"headers":[],"relativePath":"zh/classics/zhouyi/037.md","filePath":"zh/classics/zhouyi/037.md"}'),l={name:"zh/classics/zhouyi/037.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="明夷" tabindex="-1">明夷 <a class="header-anchor" href="#明夷" aria-label="Permalink to “明夷”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利艰贞。 彖曰：明入地中，明夷。内文明而外柔顺，以蒙大难，文王以之。利艰贞，晦其明也，内难而能正其志，箕子以之。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>明入地中，明夷；君子以莅众，用晦而明。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>明夷于飞，垂其翼。君子于 行，三日不食，有攸往，主人有言。象曰：君子于行，义不食也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>明夷，夷于左股，用拯马壮，吉。象曰：六二之吉，顺以则也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>明夷于南狩，得其大首，不可疾贞。象曰：南狩之志，乃大得也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>入于左腹，获明夷之心，出于门庭。象曰：入于左腹，获心意也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>箕子之明夷，利贞。象曰：箕子之贞，明不可息也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>不明晦，初登于天，后入于地。象曰：初登于天，照四国也。后入于地，失则也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
